INSERT INTO phrasebook_translations (phrase_id, lang, phrase_text, phonetic, audio_url) VALUES
(1,'pt','Olá! Tudo bem?',NULL,NULL),
(1,'en','Hello! How are you?','oh-LAH! TOO-doo BAYNG?',NULL),
(1,'es','¡Hola! ¿Qué tal?','o-LÁ! TU-du BÉIN?',NULL),
(2,'pt','Obrigado (homem) / Obrigada (mulher)',NULL,NULL),
(2,'en','Thank you','oh-bree-GAH-doo / oh-bree-GAH-dah',NULL),
(2,'es','Gracias','o-bri-GÁ-du / o-bri-GÁ-da',NULL),
(3,'pt','Você fala inglês?',NULL,NULL),
(3,'en','Do you speak English?','voh-SAY FAH-lah een-GLAYS?',NULL),
(3,'es','¿Habla usted inglés?','vo-SÉ FÁ-la in-GLÉS?',NULL),
(4,'pt','A conta, por favor.',NULL,NULL),
(4,'en','The check, please.','ah KOHN-tah, poor fah-VOR',NULL),
(4,'es','La cuenta, por favor.','a CÓN-ta, pur fa-VÓR',NULL),
(5,'pt','Sou alérgico (alérgica) a...',NULL,NULL),
(5,'en','I am allergic to...','soh ah-LEHR-zhee-koo ah...',NULL),
(5,'es','Soy alérgico (alérgica) a...','sou a-LÉR-shi-cu a...',NULL),
(6,'pt','A taxa de serviço está incluída?',NULL,NULL),
(6,'en','Is the service charge included?','ah TAH-shah jee sehr-VEE-soo eh-STAH een-kloo-EE-dah?',NULL),
(6,'es','¿Está incluida la propina?','a TÁ-sha yi ser-VÍ-su es-TÁ in-clu-Í-da?',NULL),
(7,'pt','Para este endereço, por favor.',NULL,NULL),
(7,'en','To this address, please.','PAH-rah EHS-chee en-deh-REH-soo, poor fah-VOR',NULL),
(7,'es','A esta dirección, por favor.','PA-ra ÉS-chi en-de-RÉ-su, pur fa-VÓR',NULL),
(8,'pt','Onde fica a rodoviária?',NULL,NULL),
(8,'en','Where is the bus station?','OHN-jee FEE-kah ah hoh-doh-vee-AH-ree-ah?',NULL),
(8,'es','¿Dónde está la terminal de autobuses?','ÓN-yi FÍ-ca a jo-do-vi-Á-ria?',NULL),
(9,'pt','Socorro!',NULL,NULL),
(9,'en','Help!','soh-KOH-hoo!',NULL),
(9,'es','¡Socorro!','so-CÓ-ju!',NULL),
(10,'pt','Chame a polícia!',NULL,NULL),
(10,'en','Call the police!','SHAH-mee ah poh-LEE-see-ah!',NULL),
(10,'es','¡Llame a la policía!','SHA-mi a po-LÍ-sia!',NULL),
(11,'pt','Preciso de um médico.',NULL,NULL),
(11,'en','I need a doctor.','preh-SEE-zoo jee oong MEH-jee-koo',NULL),
(11,'es','Necesito un médico.','pre-SÍ-su yi un MÉ-yi-cu',NULL),
(12,'pt','Onde fica a farmácia mais próxima?',NULL,NULL),
(12,'en','Where is the nearest pharmacy?','OHN-jee FEE-kah ah far-MAH-see-ah mice PROH-see-mah?',NULL),
(12,'es','¿Dónde está la farmacia más cercana?','ÓN-yi FÍ-ca a far-MÁ-sia mais PRÓ-si-ma?',NULL),
(13,'pt','Quanto custa?',NULL,NULL),
(13,'en','How much is it?','KWAHN-too KOOS-tah?',NULL),
(13,'es','¿Cuánto cuesta?','CUÁN-tu CÚS-ta?',NULL),
(14,'pt','Aceita cartão?',NULL,NULL),
(14,'en','Do you take cards?','ah-SAY-tah kar-TOWNG?',NULL),
(14,'es','¿Acepta tarjeta?','a-SÉI-ta car-TÁUN?',NULL),
(15,'pt','Com licença, por favor.',NULL,NULL),
(15,'en','Excuse me, please.','kohn lee-SEN-sah, poor fah-VOR',NULL),
(15,'es','Con permiso, por favor.','con li-SEN-sa, pur fa-VÓR',NULL),
(16,'pt','Desculpe, não entendi. Pode repetir mais devagar?',NULL,NULL),
(16,'en','Sorry, I did not catch that. Could you speak more slowly?','jehs-KOOL-pee, nowng en-ten-JEE. POH-jee heh-peh-CHEER mice jeh-vah-GAR?',NULL),
(16,'es','Disculpe, no entendí. ¿Puede repetir más despacio?','des-CÚL-pi, náun en-ten-YÍ. PÓ-yi re-pe-TÍR mais de-va-GÁR?',NULL),
(17,'pt','Bom dia! Tudo certo por aqui?',NULL,NULL),
(17,'en','Good morning! How is everything going?','bohm JEE-ah! TOO-doo SEHR-too poor ah-KEE?',NULL),
(17,'es','¡Buenos días! ¿Todo bien por aquí?','bóun YÍ-a! TÚ-du SÉR-tu pur a-QUÍ?',NULL),
(18,'pt','Onde fica o banheiro, por favor?',NULL,NULL),
(18,'en','Where is the restroom, please?','OHN-jee FEE-kah oo bahn-YAY-roo, poor fah-VOR?',NULL),
(18,'es','¿Dónde está el baño, por favor?','ÓN-yi FÍ-ca u ba-ÑÉI-ru, pur fa-VÓR?',NULL),
(19,'pt','Você recomenda algum prato típico daqui?',NULL,NULL),
(19,'en','Do you recommend any local specialty?','voh-SAY heh-koh-MEN-dah ahl-GOONG PRAH-too CHEE-pee-koo dah-KEE?',NULL),
(19,'es','¿Recomienda algún plato típico de aquí?','vo-SÉ re-co-MÉN-da al-GÚN PRÁ-tu TÍ-pi-cu da-QUÍ?',NULL),
(20,'pt','Gostaria de uma água sem gás, por favor.',NULL,NULL),
(20,'en','I would like a still water, please.','gohs-tah-REE-ah jee OO-mah AH-gwah sayng gahs, poor fah-VOR',NULL),
(20,'es','Quisiera un agua sin gas, por favor.','gos-ta-RÍ-a yi Ú-ma Á-gua sein gas, pur fa-VÓR',NULL),
(21,'pt','Tem opção vegetariana ou sem glúten?',NULL,NULL),
(21,'en','Do you have a vegetarian or gluten-free option?','tayng ohp-SOWNG veh-jeh-tah-ree-AH-nah oh sayng GLOO-ten?',NULL),
(21,'es','¿Tienen opción vegetariana o sin gluten?','tein op-SÁUN ve-she-ta-ri-Á-na ou sein GLÚ-ten?',NULL),
(22,'pt','Estava tudo delicioso, muito obrigado!',NULL,NULL),
(22,'en','Everything was delicious, thank you very much!','ehs-TAH-vah TOO-doo deh-lee-see-OH-zoo, MOOY-too oh-bree-GAH-doo!',NULL),
(22,'es','¡Estaba todo delicioso, muchas gracias!','es-TÁ-va TÚ-du de-li-si-Ó-zu, MÚI-tu o-bri-GÁ-du!',NULL),
(23,'pt','Qual é a estação de metrô mais próxima?',NULL,NULL),
(23,'en','Where is the nearest subway station?','kwahl eh ah ehs-tah-SOWNG jee meh-TROH mice PROH-see-mah?',NULL),
(23,'es','¿Cuál es la estación de metro más cercana?','cuál é a es-ta-SÁUN yi me-TRÓ mais PRÓ-si-ma?',NULL),
(24,'pt','Este ônibus passa pelo centro?',NULL,NULL),
(24,'en','Does this bus go through downtown?','EHS-chee OH-nee-boos PAH-sah PEH-loo SEN-troo?',NULL),
(24,'es','¿Este autobús pasa por el centro?','ÉS-chi Ó-ni-bus PÁ-sa PE-lu SEN-tru?',NULL),
(25,'pt','Quanto tempo leva até o aeroporto?',NULL,NULL),
(25,'en','How long does it take to get to the airport?','KWAHN-too TEM-poo LEH-vah ah-TEH oo ah-eh-roh-POR-too?',NULL),
(25,'es','¿Cuánto tiempo se tarda hasta el aeropuerto?','CUÁN-tu TEM-pu LÉ-va a-TÉ u a-e-ro-PÓR-tu?',NULL),
(26,'pt','Pode me avisar quando chegarmos lá?',NULL,NULL),
(26,'en','Could you let me know when we get there?','POH-jee mee ah-vee-ZAR KWAHN-doo sheh-GAR-moos lah?',NULL),
(26,'es','¿Me puede avisar cuando lleguemos?','PÓ-yi mi a-vi-ZÁR CUÁN-du she-GÁR-mus lá?',NULL),
(27,'pt','Quero pedir um carro por aplicativo.',NULL,NULL),
(27,'en','I would like to call a rideshare car.','KEH-roo peh-JEER oong KAH-hoo poor ah-plee-kah-CHEE-voo',NULL),
(27,'es','Quiero pedir un auto por aplicación.','QUÉ-ru pe-YÍR un CÁ-ju pur a-pli-ca-CHÍ-vu',NULL),
(28,'pt','Perdi meu passaporte, preciso da polícia turística.',NULL,NULL),
(28,'en','I lost my passport, I need the tourist police.','pehr-JEE meh-oo pah-sah-POR-chee, preh-SEE-zoo dah poh-LEE-see-ah too-REES-chee-kah',NULL),
(28,'es','Perdí mi pasaporte, necesito a la policía turística.','per-YÍ meu pa-sa-PÓR-chi, pre-SÍ-zu da po-LÍ-sia tu-RÍS-chi-ca',NULL),
(29,'pt','Por favor, ligue para a minha embaixada.',NULL,NULL),
(29,'en','Please call my embassy.','poor fah-VOR, LEE-gee PAH-rah ah MEEN-yah em-bye-SHAH-dah',NULL),
(29,'es','Por favor, llame a mi embajada.','pur fa-VÓR, LÍ-gui PA-ra a MI-ña em-bai-SHÁ-da',NULL),
(30,'pt','Fui assaltado, preciso fazer um boletim de ocorrência.',NULL,NULL),
(30,'en','I was robbed, I need to file a police report.','foo-ee ah-sahl-TAH-doo, preh-SEE-zoo fah-ZEHR oong boh-leh-CHEENG jee oh-koh-HEN-see-ah',NULL),
(30,'es','Me robaron, necesito hacer una denuncia.','fúi a-sal-TÁ-du, pre-SÍ-zu fa-ZÉR un bo-le-CHÍN yi o-co-RÉN-sia',NULL),
(31,'pt','Não me sinto seguro aqui, pode me ajudar?',NULL,NULL),
(31,'en','I do not feel safe here, can you help me?','nowng mee SEEN-too seh-GOO-roo ah-KEE, POH-jee mee ah-joo-DAR?',NULL),
(31,'es','No me siento seguro aquí, ¿puede ayudarme?','náun mi SÍN-tu se-GÚ-ru a-QUÍ, PÓ-yi mi a-zhu-DÁR?',NULL),
(32,'pt','Onde fica o hospital ou UPA mais próximo?',NULL,NULL),
(32,'en','Where is the nearest hospital or urgent care?','OHN-jee FEE-kah oo ohs-pee-TAHL oh OO-pah mice PROH-see-moo?',NULL),
(32,'es','¿Dónde está el hospital o guardia más cercana?','ÓN-yi FÍ-ca u os-pi-TÁL ou Ú-pa mais PRÓ-si-mu?',NULL),
(33,'pt','Estou com muita febre e dor no corpo.',NULL,NULL),
(33,'en','I have a high fever and body aches.','ehs-TOH kohng MOOY-tah FEH-bree ee dor noo KOR-poo',NULL),
(33,'es','Tengo mucha fiebre y dolor en el cuerpo.','es-TÓU con MÚI-ta FÉ-bri i dor nu CÓR-pu',NULL),
(34,'pt','Tenho seguro-viagem, este é o meu contato.',NULL,NULL),
(34,'en','I have travel insurance, here is my contact info.','TEN-yoo seh-GOO-roo vee-AH-jeng, EHS-chee eh oo meh-oo kohn-TAH-too',NULL),
(34,'es','Tengo seguro de viaje, este es mi contacto.','TÉ-ñu se-GÚ-ru vi-Á-shein, ÉS-chi é u meu con-TÁ-tu',NULL),
(35,'pt','Preciso de um remédio para dor de cabeça.',NULL,NULL),
(35,'en','I need medicine for a headache.','preh-SEE-zoo jee oong heh-MEH-jee-oo PAH-rah dor jee kah-BEH-sah',NULL),
(35,'es','Necesito un medicamento para el dolor de cabeza.','pre-SÍ-zu yi un re-MÉ-yi-u PA-ra dor yi ca-BÉ-sa',NULL),
(36,'pt','Estou com alergia ou intoxicação alimentar.',NULL,NULL),
(36,'en','I am having an allergic reaction or food poisoning.','ehs-TOH kohng ah-lehr-ZHEE-ah oh een-tohk-see-kah-SOWNG ah-lee-men-TAR',NULL),
(36,'es','Tengo una alergia o intoxicación alimentaria.','es-TÓU con a-ler-SHÍ-a ou in-toc-si-ca-SÁUN a-li-men-TÁR',NULL),
(37,'pt','Preciso de receita médica para comprar isso?',NULL,NULL),
(37,'en','Do I need a prescription to buy this?','preh-SEE-zoo jee heh-SAY-tah MEH-jee-kah PAH-rah kohm-PRAR EE-soo?',NULL),
(37,'es','¿Necesito receta médica para comprar esto?','pre-SÍ-zu yi re-SÉI-ta MÉ-yi-ca PA-ra com-PRÁR Í-su?',NULL),
(38,'pt','Aceita pagamento por aproximação ou PIX?',NULL,NULL),
(38,'en','Do you accept contactless payment or PIX?','ah-SAY-tah pah-gah-MEN-too poor ah-proh-see-mah-SOWNG oh peeks?',NULL),
(38,'es','¿Acepta pago sin contacto o PIX?','a-SÉI-ta pa-ga-MÉN-tu pur a-pro-si-ma-SÁUN ou pics?',NULL),
(39,'pt','Tem desconto se eu pagar no dinheiro?',NULL,NULL),
(39,'en','Is there a discount if I pay in cash?','tayng jehs-KOHN-too see eh-oo pah-GAR noo jeen-YAY-roo?',NULL),
(39,'es','¿Hay descuento si pago en efectivo?','tein des-CÓN-tu si eu pa-GÁR nu yi-ÑÉI-ru?',NULL),
(40,'pt','Posso experimentar este tamanho?',NULL,NULL),
(40,'en','Can I try on this size?','POH-soo ehs-peh-ree-men-TAR EHS-chee tah-MAHN-yoo?',NULL),
(40,'es','¿Puedo probarme este talle?','PÓ-su es-pe-ri-men-TÁR ÉS-chi ta-MÁ-ñu?',NULL),
(41,'pt','Vocês fazem nota fiscal ou recibo?',NULL,NULL),
(41,'en','Can you give me an official receipt?','voh-SAYS FAH-zeng NOH-tah fees-KAHL oh heh-SEE-boo?',NULL),
(41,'es','¿Me puede dar un recibo o factura?','vo-SÉS FÁ-zein NÓ-ta fis-CÁL ou re-SÍ-bu?',NULL),
(42,'pt','Estou só dando uma olhada, obrigado!',NULL,NULL),
(42,'en','I am just browsing, thank you!','ehs-TOH soh DAHN-doo OO-mah ohl-YAH-dah, oh-bree-GAH-doo!',NULL),
(42,'es','Estoy solo mirando, ¡gracias!','es-TÓU só DÁN-du Ú-ma o-LÁ-da, o-bri-GÁ-du!',NULL);
