INSERT INTO phrasebook_translations (phrase_id, lang, phrase_text, phonetic, audio_url) VALUES
(43,'pt','Bom dia! / Boa tarde! / Boa noite!',NULL,NULL),
(43,'en','Good morning! / Good afternoon! / Good evening!','bohm JEE-ah! / BOH-ah TAR-jee! / BOH-ah NOY-chee!',NULL),
(43,'es','¡Buenos días! / ¡Buenas tardes! / ¡Buenas noches!','bóun YÍ-a! / BÓ-a TÁR-yi! / BÓ-a NÓI-chi!',NULL),
(44,'pt','Fale mais devagar, por favor.',NULL,NULL),
(44,'en','Please speak more slowly.','FAH-lee mice jeh-vah-GAR, poor fah-VOR.',NULL),
(44,'es','Hable más despacio, por favor.','FÁ-li mais de-va-GÁR, pur fa-VÓR.',NULL),
(45,'pt','Eu não falo português.',NULL,NULL),
(45,'en','I don''t speak Portuguese.','eh-oo nowng FAH-loo por-too-GAYS.',NULL),
(45,'es','No hablo portugués.','eu náun FÁ-lu por-tu-GUÉS.',NULL),
(46,'pt','Pode me ajudar?',NULL,NULL),
(46,'en','Can you help me?','POH-jee mee ah-joo-DAR?',NULL),
(46,'es','¿Puede ayudarme?','PÓ-yi mi a-zhu-DÁR?',NULL),
(47,'pt','Qual é a senha do Wi-Fi?',NULL,NULL),
(47,'en','What is the Wi-Fi password?','kwahl eh ah SEN-yah doo why-fye?',NULL),
(47,'es','¿Cuál es la contraseña del Wi-Fi?','cuál é a SÉ-ña du uái-fái?',NULL),
(48,'pt','Uma mesa para duas pessoas, por favor.',NULL,NULL),
(48,'en','A table for two, please.','OO-mah MEH-zah PAH-rah DOO-ahs peh-SOH-ahs, poor fah-VOR.',NULL),
(48,'es','Una mesa para dos personas, por favor.','Ú-ma MÉ-za PA-ra DÚ-as pe-SÓ-as, pur fa-VÓR.',NULL),
(49,'pt','Pode trazer o cardápio?',NULL,NULL),
(49,'en','Can you bring the menu?','POH-jee trah-ZEHR oo kar-DAH-pee-oo?',NULL),
(49,'es','¿Me puede traer el menú?','PÓ-yi tra-ZÉR u car-DÁ-pi-u?',NULL),
(50,'pt','Sou vegetariano (vegetariana).',NULL,NULL),
(50,'en','I''m vegetarian.','soh veh-jeh-tah-ree-AH-noo (veh-jeh-tah-ree-AH-nah).',NULL),
(50,'es','Soy vegetariano (vegetariana).','sóu ve-she-ta-ri-Á-nu (ve-she-ta-ri-Á-na).',NULL),
(51,'pt','Pode ser para viagem?',NULL,NULL),
(51,'en','Can I get it to go?','POH-jee sehr PAH-rah vee-AH-jeng?',NULL),
(51,'es','¿Puede ser para llevar?','PÓ-yi ser PA-ra vi-Á-shein?',NULL),
(52,'pt','Podemos pagar separado?',NULL,NULL),
(52,'en','Can we pay separately?','poh-DEH-moos pah-GAR seh-pah-RAH-doo?',NULL),
(52,'es','¿Podemos pagar por separado?','po-DÉ-mus pa-GÁR se-pa-RÁ-du?',NULL),
(53,'pt','Quanto custa a corrida até...?',NULL,NULL),
(53,'en','How much is the ride to...?','KWAHN-too KOOS-tah ah koh-HEE-dah ah-TEH...?',NULL),
(53,'es','¿Cuánto cuesta el viaje hasta...?','CUÁN-tu CÚS-ta a co-RÍ-da a-TÉ...?',NULL),
(54,'pt','Esse ônibus vai para...?',NULL,NULL),
(54,'en','Does this bus go to...?','EHS-see OH-nee-boos vye PAH-rah...?',NULL),
(54,'es','¿Este autobús va hacia...?','ÉS-si Ó-ni-bus vái PA-ra...?',NULL),
(55,'pt','A que horas sai o próximo ônibus?',NULL,NULL),
(55,'en','What time is the next bus?','ah keh OH-rahs sye oo PROH-see-moo OH-nee-boos?',NULL),
(55,'es','¿A qué hora sale el próximo autobús?','a qui Ó-ras sái u PRÓ-si-mu Ó-ni-bus?',NULL),
(56,'pt','Onde fica o ponto de ônibus?',NULL,NULL),
(56,'en','Where is the bus stop?','OHN-jee FEE-kah oo POHN-too jee OH-nee-boos?',NULL),
(56,'es','¿Dónde está la parada de autobús?','ÓN-yi FÍ-ca u PÓN-tu yi Ó-ni-bus?',NULL),
(57,'pt','Preciso de uma ambulância!',NULL,NULL),
(57,'en','I need an ambulance!','preh-SEE-zoo jee OO-mah ahm-boo-LAHN-see-ah!',NULL),
(57,'es','¡Necesito una ambulancia!','pre-SÍ-zu yi Ú-ma am-bu-LÁN-sia!',NULL),
(58,'pt','Onde fica a delegacia mais próxima?',NULL,NULL),
(58,'en','Where is the nearest police station?','OHN-jee FEE-kah ah deh-leh-gah-SEE-ah mice PROH-see-mah?',NULL),
