(5,'en','Chapada dos Veadeiros Canyons & Waterfalls','Four days of crystal clear waterfalls and quartzite canyons in Goiás.',
 '{"best_season":"May to September (dry season, blue skies, safe swimming)","estimated_cost":"USD 70-150 per day","logistics":"Fly to Brasília (BSB). Rent a car or take executive bus to Alto Paraíso de Goiás (230 km, ~3 hours).","days":[{"day":1,"title":"Arrival in Alto Paraíso & Loquinhas","items":["Scenic drive from Brasília through the Cerrado plateau","Afternoon swim at Cachoeira das Loquinhas (emerald pools)","Dinner in Vila de São Jorge"]},{"day":2,"title":"Veadeiros National Park (Canyon II & Carioquinhas)","items":["Hike inside the National Park (Trail of the Canyons)","Swimming in Rio Preto natural pools","Sunset at Jardim de Maytrea"]},{"day":3,"title":"Catarata dos Couros","items":["Full-day excursion on gravel road to Couros waterfalls","Multi-tiered massive waterfalls and natural cliff jumping","Traditional Goiás lunch at Dona Dalva farm"]},{"day":4,"title":"Almécegas & Return to Brasília","items":["Morning visit to Fazenda São Bento (Almécegas I and II)","Scenic return drive to Brasília Airport"]}],"tips":["Sturdy hiking shoes with good grip on wet rocks are essential","Cerrado weather is very dry in winter — drink plenty of water","Car hire from BSB airport is the most practical way to get around"]}'),
(5,'pt','Cânions e Cachoeiras da Chapada dos Veadeiros','Quatro dias de cachoeiras de águas cristalinas e cânions de quartzito no Cerrado.',
 '{"best_season":"Maio a setembro (estação seca, céu azul e banhos seguros)","estimated_cost":"USD 70-150 por dia","logistics":"Voo até Brasília (BSB). Alugue um carro ou pegue ônibus até Alto Paraíso de Goiás (230 km, ~3h de viagem).","days":[{"day":1,"title":"Chegada em Alto Paraíso e Loquinhas","items":["Viagem cênica de Brasília até a Chapada pelo planalto central","Banho de tarde nos poços cor esmeralda das Loquinhas","Jantar na charmosa Vila de São Jorge"]},{"day":2,"title":"Parque Nacional da Chapada dos Veadeiros","items":["Trilha dos Cânions e Cachoeira das Carioquinhas no Parque Nacional","Banho no Rio Preto","Pôr do sol místico no Jardim de Maytrea"]},{"day":3,"title":"Catarata dos Couros","items":["Expedição de dia inteiro até as gigantescas quedas dos Couros","Banho e contemplação nos mirantes","Almoço com comida típica goiana na Fazenda da Dona Dalva"]},{"day":4,"title":"Almécegas e Retorno a Brasília","items":["Visita matutina à Fazenda São Bento (Almécegas I e II)","Viagem de volta ao Aeroporto de Brasília"]}],"tips":["Tênis ou bota de trilha com excelente aderência a pedras molhadas","O Cerrado é muito seco no meio do ano: hidrate-se com frequência","Alugar carro em Brasília é a melhor opção de mobilidade"]}'),
(6,'en','Serra da Mantiqueira & Monte Verde Alpine Escape','Three days of cool mountain air, panoramic peaks, and cozy fireside gastronomy in Minas Gerais.',
 '{"best_season":"May to August (winter, crisp mountain skies, romantic atmosphere)","estimated_cost":"USD 90-200 per day","logistics":"2.5 hours by car from São Paulo Guarulhos Airport (GRU) via Fernão Dias highway (BR-381).","days":[{"day":1,"title":"Scenic Arrival & Fondue Evening","items":["Drive up the pine-lined Mantiqueira mountains","Check-in to a cozy chalet with fireplace","Evening alpine cheese fondue and regional craft beer along the main avenue"]},{"day":2,"title":"Panoramic Mountain Peaks","items":["Morning guided hike to Pedra Redonda peak (breathtaking 360 view)","Visit to local craft distilleries and chocolate ateliers","Afternoon tea at Unger Pottery House gallery"]},{"day":3,"title":"Pedra Partida & Departure","items":["Challenging hike to Pedra Partida for adventurous travelers","Traditional Minas farmhouse lunch with fresh trout","Leisurely scenic drive back to São Paulo"]}],"tips":["Bring warm clothing — temperatures drop close to 0°C (32°F) on winter nights","Book accommodation well in advance for winter weekends"]}'),
(6,'pt','Serra da Mantiqueira & Monte Verde Romântico','Três dias de clima serrano, picos com vista panorâmica e gastronomia de lareira no sul de Minas.',
 '{"best_season":"Maio a agosto (inverno serrano, céu azul e fondues)","estimated_cost":"USD 90-200 por dia","logistics":"2h30 de carro saindo do Aeroporto de Guarulhos (GRU) pela Rodovia Fernão Dias (BR-381).","days":[{"day":1,"title":"Subida da Serra & Noite de Fondue","items":["Subida panorâmica entre araucárias e montanhas","Check-in em chalé com lareira","Jantar de fondue e cervejas artesanais na charmosa avenida principal"]},{"day":2,"title":"Picos Panorâmicos da Mantiqueira","items":["Trilha até o topo da Pedra Redonda (vista 360 graus espetacular)","Visita às chocolaterias artesanais e ateliês de cerâmica","Tarde contemplativa na galeria Unger Pottery House"]},{"day":3,"title":"Pedra Partida & Retorno","items":["Trilha da Pedra Partida para quem busca mais aventura","Almoço mineiro com truta fresca regional","Descida tranquila da serra de volta a São Paulo"]}],"tips":["Leve agasalhos pesados: as noites de inverno chegam perto de 0°C","Reserve pousada com antecedência para os fins de semana do Festival de Inverno"]}'),
(7,'en','Chapada Diamantina Heart of Bahia Expedition','Five days of monumental table-top plateaus, underground azure pools, and colossal waterfalls.',
 '{"best_season":"April to October (sunny days, ideal hiking weather)","estimated_cost":"USD 80-180 per day","logistics":"Fly to Salvador (SSA), then take a regional flight or comfortable 6-hour executive bus to Lençóis.","days":[{"day":1,"title":"Colonial Lençóis & Morro do Pai Inácio","items":["Arrival in the diamond-era colonial town of Lençóis","Afternoon hike up Morro do Pai Inácio for the legendary sunset over the canyons","Dinner in Lençóis historic center"]},{"day":2,"title":"Fumaça Waterfall (340m drop)","items":["Trek to the top of Cachoeira da Fumaça (one of South Americas highest falls)","Valley views from the cliff edge","Swimming at Riachinho waterfall"]},{"day":3,"title":"Sunken Caves: Poço Azul & Poço Encantado","items":["Visit to Poço Encantado (cave with impossibly clear blue water illuminated by sunbeam)","Snorkeling with lifevests inside Poço Azul"]},{"day":4,"title":"Pratinha Caves & Zipline","items":["Explore Gruta da Pratinha and Gruta Azul","Stand-up paddle and cave snorkeling in underground river"]},{"day":5,"title":"Sossego Canyon & Return","items":["Hike through riverbeds to Cachoeira do Sossego","Return transfer to Salvador"]}],"tips":["Hire an experienced local guide from the Lençóis Guide Association","Carry waterproof pouch for your phone and electronics"]}'),
(7,'pt','Expedição Chapada Diamantina na Bahia','Cinco dias de cânions monumentais, poços azuis subterrâneos e cachoeiras colossais.',
 '{"best_season":"Abril a outubro (dias ensolarados e clima ideal para trilhas)","estimated_cost":"USD 80-180 por dia","logistics":"Voo até Salvador (SSA) e traslado de 6h em ônibus executivo confortável ou voo regional até Lençóis.","days":[{"day":1,"title":"Lençóis Histórica & Pôr do Sol no Pai Inácio","items":["Chegada na cidade colonial dos garimpeiros em Lençóis","Subida cênica ao Morro do Pai Inácio para o pôr do sol clássico sobre os platôs","Jantar no casario iluminado de Lençóis"]},{"day":2,"title":"Cachoeira da Fumaça (340 metros)","items":["Trilha até o topo da Fumaça, uma das maiores quedas do continente","Visão deitada na pedra sobre o abismo","Banho relaxante na Cachoeira do Riachinho"]},{"day":3,"title":"Cavernas Azuis: Poço Encantado & Poço Azul","items":["Contemplação do raio de sol no Poço Encantado","Flutuação com colete salva-vidas nas águas cristalinas do Poço Azul"]},{"day":4,"title":"Fazenda Pratinha & Gruta Azul","items":["Mergulho de snorkel na caverna aquática da Pratinha","Fotos na Gruta Azul e tirolesa panorâmica"]},{"day":5,"title":"Cachoeira do Sossego e Retorno","items":["Trilha pelo leito de pedras até o cânion do Sossego","Traslado de retorno para Salvador"]}],"tips":["Contrate sempre condutores credenciados da Associação de Guias de Lençóis","Leve protetor solar biodegradável e calçados que possam molhar"]}'),
(8,'en','Iguaçu Falls & Triple Border Wonder','Three days marveling at the world largest waterfall system and subtropical rainforest.',
 '{"best_season":"All year (summer has maximum water volume; winter has clearest blue skies)","estimated_cost":"USD 100-220 per day","logistics":"Fly directly to Foz do Iguaçu Airport (IGU). Most hotels are 15-20 min from airport and park gates.","days":[{"day":1,"title":"Brazilian Falls & Macuco Safari","items":["Panoramic walkway with full frontal views of the Falls inside Iguaçu National Park","Macuco Safari thrilling speedboat ride right beneath the roaring waterfalls","Helicopter flight over the Devil Throat (optional)"]},{"day":2,"title":"Parque das Aves & Itaipu Dam","items":["Immersion aviaries at Parque das Aves (toucans, macaws, and flamingos)","Tour of Itaipu Binacional (one of the modern engineering wonders of the world)","Sunset dinner overlooking the Paraná and Iguaçu River Triple Border"]},{"day":3,"title":"Argentinean Side Excursion & Departure","items":["Cross to Iguazú National Park (Argentina) to stand right over the roaring Garganta del Diablo","Return transfer to IGU airport"]}],"tips":["Bring a reliable waterproof poncho and dry bag for cameras during boat rides","Check if you need reciprocal visa or stamp for day trip to Argentinean side"]}'),
(8,'pt','Cataratas do Iguaçu e Tríplice Fronteira','Três dias diante do maior conjunto de quedas d água do planeta e da mata atlântica subtropical.',
 '{"best_season":"O ano todo (verão com vazão máxima de água; inverno com céu limpo e menos umidade)","estimated_cost":"USD 100-220 por dia","logistics":"Voo direto até o Aeroporto de Foz do Iguaçu (IGU). Hotéis ficam a 15-20 min das atrações.","days":[{"day":1,"title":"Lado Brasileiro das Cataratas & Macuco Safari","items":["Caminhada pelas passarelas panorâmicas do Parque Nacional do Iguaçu","Passeio de barco inflável Macuco Safari batizando embaixo das quedas d água","Mirante da Garganta do Diabo com arco-íris frontal"]},{"day":2,"title":"Parque das Aves & Usina de Itaipu","items":["Viveiros de imersão no Parque das Aves (araras, tucanos e harpias)","Visita panorâmica à gigantesca Usina Binacional de Itaipu","Pôr do sol no Marco das Três Fronteiras com show cultural"]},{"day":3,"title":"Lado Argentino & Despedida","items":["Passeio até a passarela argentina que termina exatamente acima da Garganta del Diablo","Compras de artesanato e alfajores em Puerto Iguazú","Traslado de volta ao aeroporto de Foz"]}],"tips":["Capa de chuva e saco estanque para celular são indispensáveis no Macuco Safari","Leve documento com foto para cruzar a fronteira de Puerto Iguazú"]}'),
(9,'en','Acre: Amazonian Rubber Trails & Rio Branco','Three days exploring Amazonian forest history, Chico Mendes heritage, and riverfront gastronomy in Acre.',
 '{"best_season":"May to September (dry Amazonian season)","estimated_cost":"USD 65-130 per day","logistics":"Fly into Rio Branco Airport (RBR). Rent a car or book guided day trips to Xapuri (180 km).","days":[{"day":1,"title":"Rio Branco Historic Center","items":["Visit Palácio Rio Branco and Museu da Borracha","Walk across Passarela Joaquim Macedo over the Acre River","Try baixaria and tacacá at Mercado Velho"]},{"day":2,"title":"Xapuri & Chico Mendes Legacy","items":["Day trip to Xapuri and Casa de Chico Mendes","Guided trail inside Seringal Cachoeira","Meet local rubber tappers and taste fresh Brazil nuts"]},{"day":3,"title":"Parque Ambiental Chico Mendes & Departure","items":["Morning wildlife walk at Parque Ambiental Chico Mendes","Handicraft shopping at Casa do Artesão Acreano","Transfer to RBR airport"]}],"tips":["Check yellow fever vaccination before traveling","Carry insect repellent and light breathable clothes"]}'),
(9,'pt','Acre: Rio Branco, Xapuri & Seringais Amazônicos','Três dias pela história dos seringais, o legado de Chico Mendes e a gastronomia amazônica do Acre.',
